/**
 * Builds the browser bundle that index.html's Live Preview renders with.
 *
 * The preview used to be a second, hand-written implementation of every
 * component (`PG[id].impl`), independent of packages/react-ui. Two transcripts
 * of the same Figma spec drift, and they did: Sold Out sat in the wrong corner,
 * Point/Balance had both of its gaps wrong, ProductCard fell back to emoji
 * icons. Every one of those was invisible on the docs site, because the docs
 * site was not rendering the package.
 *
 * So the preview renders the real thing now. Output goes to assets/ui/ and is
 * committed, because packages/react-ui/dist is gitignored and GitHub Pages
 * could not serve it.
 *
 * Run after any change to packages/react-ui:
 *   node scripts/build-docs-bundle.js
 */
const path = require('path');
const fs = require('fs');

const ROOT = path.join(__dirname, '..');
// esbuild ships as a tsup dependency of the package we are bundling.
const { build } = require(path.join(ROOT, 'packages', 'react-ui', 'node_modules', 'esbuild'));

const OUT = path.join(ROOT, 'assets', 'ui', 'snacky-ui.js');

const BANNER = `/*! Snacky UI - generated by scripts/build-docs-bundle.js, do not hand-edit.
 * Browser bundle of packages/react-ui, so index.html's Live Preview renders the
 * same code the npm package ships instead of a parallel hand-written copy.
 * Icon artwork: UIcons by Flaticon (https://www.flaticon.com/uicons), used under
 * CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/) and modified.
 * See NOTICE at the repo root. */`;

fs.mkdirSync(path.dirname(OUT), { recursive: true });

build({
  entryPoints: [path.join(__dirname, 'docs-bundle-entry.js')],
  bundle: true,
  // The entry lives in scripts/, but react + react-dom are installed under the
  // package being bundled, so resolution has to be pointed there.
  nodePaths: [path.join(ROOT, 'packages', 'react-ui', 'node_modules')],
  format: 'iife',
  jsx: 'automatic',
  target: ['es2019'],
  minify: true,
  sourcemap: false,
  define: { 'process.env.NODE_ENV': '"production"' },
  banner: { js: BANNER },
  outfile: OUT,
})
  .then(() => {
    const css = OUT.replace(/\.js$/, '.css');
    const kb = (f) => (fs.statSync(f).size / 1024).toFixed(1) + ' KB';
    const parts = [`snacky-ui.js ${kb(OUT)}`];
    if (fs.existsSync(css)) parts.push(`snacky-ui.css ${kb(css)}`);
    else console.warn('WARNING: no CSS emitted - the preview would render unstyled');
    console.log('Wrote assets/ui/: ' + parts.join(', '));
  })
  .catch((err) => {
    console.error(err);
    process.exit(1);
  });
